        # Check if field starts with quote
        if line[i] == '"':
            # Parse quoted field
            field = ""
            i += 1  # Skip opening quote
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] != ',':
                                return None
                            i += 1  # Skip comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(field)
        else:
            # Parse unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            # Skip comma if present
            if i < len(line):
                i += 1  # Skip comma

    return fields

